  <div style={{margin:'0.75rem 0',padding:'0.6rem 0.85rem',background:'#f0fdf4',border:'1px solid #bbf7d0',borderRadius:'8px',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
    <span style={{fontSize:'0.8rem',color:'#166534',fontWeight:500}}>⚡ Seeded demo personas ready</span>
    <button type="button" className="btn btn-secondary small-btn" style={{fontSize:'0.75rem',padding:'0.25rem 0.6rem'}} onClick={()=>setHelpOpen(true)}>Choose Persona &rarr;</button>
  </div>
